const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const esc = (v) => String(v ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
let C = CATALOG || {site:{},apps:[],categories:[],platforms:[],tiers:[]};
const P = CONFIG || {tiers:{},plans:[],payment:{},adsense:{},chat:{},request:{},social:{}};
const SITE = C.site || {name:"MH Apps Gallery",url:"https://mhappsgallery.blogspot.com"};
const S = {
  query:"", category:"All", platform:"All", tier:"All", sort:"latest", shown:12,
  favorites:new Set(JSON.parse(SAFE.get("mhag2-favs")||"[]")),
  theme:SAFE.get("mhag2-theme")||"dark", current:null
};
const reduced = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/* ---------- helpers ---------- */
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(toast._t);toast._t=setTimeout(()=>t.classList.remove("show"),3400);}
function pal(name){const p=[["#1b6ef3","#f472b6"],["#7c3aed","#f472b6"],["#0ea5e9","#6366f1"],["#06b6d4","#a855f7"],["#4f46e5","#0ea5e9"],["#2563eb","#38bdf8"]];let h=0;for(const c of name)h=(h*31+c.charCodeAt(0))>>>0;return p[h%p.length];}
function icon(a,size){const [x,y]=pal(a.name||a.id||"MH");const ini=(a.name||"MH").split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0].toUpperCase()).join("")||"MH";
  return `<div class="app-icon" style="${size?`width:${size}px;height:${size}px;`:''}background:linear-gradient(135deg,${x},${y})"><span>${esc(ini)}</span>${a.image&&a.image.startsWith("http")?`<img loading="lazy" alt="" src="${esc(a.image)}" onerror="this.style.display='none'">`:""}</div>`;}
function tierBadge(a){return a.tier==="premium"?'<span class="badge b-prem">★ PREMIUM</span>':'<span class="badge b-free">FREE</span>';}
function findApp(id){return C.apps.find(a=>a.id===String(id));}
function firstDownload(a){return (a.downloads||[]).find(d=>d.kind==="official")||(a.downloads||[])[0]||null;}
function pageUrl(a){return a&&a.postUrl?a.postUrl:SITE.url;}
function shareText(a){return a?`${a.name} — ${a.summary||SITE.tagline||"MH Apps Gallery"}`:`${SITE.name} — ${SITE.tagline||"Your Apps & Software Hub"}`;}
function enc(s){return encodeURIComponent(s);}

/* ---------- Ad networks: AdSense + Adsterra ---------- */
function configuredNetworks(){
  const cfg=P.adNetwork||{}, opts=cfg.options||["adsense","adsterra","both","off"];
  let active=cfg.active||"adsense";
  try{
    const q=new URLSearchParams(location.search).get(cfg.previewParam||"ads");
    if(q&&opts.includes(q))active=q;
  }catch(_){}
  if(active==="both"&&cfg.allowBoth===false)active="adsense";
  if(active==="off")return [];
  if(active==="both")return ["adsense","adsterra"];
  return opts.includes(active)?[active]:["adsense"];
}
function adsenseMarkup(key){
  const a=P.adsense||{}, client=a.client||"", slot=(a.slots||{})[key]||"";
  const ready=a.enabled && client && !client.includes("XXXX");
  if(ready && slot){
    return `<ins class="adsbygoogle" style="display:block" data-ad-client="${esc(client)}" data-ad-slot="${esc(slot)}" data-ad-format="auto" data-full-width-responsive="true"></ins>`;
  }
  if(ready && a.autoAds){
    return `<div class="ad-slot-placeholder ad-auto">ADVERTISEMENT · AdSense Auto ads active (${esc(client)}) — add this position's ad unit ID in <b>config/pricing.json</b> for a fixed slot</div>`;
  }
  return `<div class="ad-slot-placeholder">ADVERTISEMENT · AdSense ${esc(key)} slot — set client + slot IDs in <b>config/pricing.json</b> (or add an AdSense gadget in Blogger Layout)</div>`;
}
function adsterraMarkup(key){
  const a=P.adsterra||{};
  if(!a.enabled)return `<div class="ad-slot-placeholder">ADVERTISEMENT · Adsterra ${esc(key)} slot — set <b>adsterra.enabled=true</b> and paste your code/URL in <b>config/pricing.json</b></div>`;
  const pl=(a.placements||{})[key]||{};
  const code=pl.scriptUrl||pl.html||pl.link||a.directLink||a.defaultBannerHtml||"";
  if(!code)return `<div class="ad-slot-placeholder ad-auto">ADVERTISEMENT · Adsterra active — paste this position's <b>scriptUrl / html / link</b> in <b>config/pricing.json</b></div>`;
  const m=String(code).match(/<script[^>]+src=["']([^"']+)["']/i);
  const src=pl.scriptUrl||(m&&m[1])||(/^(https?:)?\/\//.test(code)&&/\.js(\?|$)/.test(code)?code:"");
  if(src)return `<div class="adsterra-slot" data-adsterra-src="${esc(src)}"></div>`;
  if(/^(https?:)?\/\//.test(code))return `<a class="adsterra-link" href="${esc(code)}" target="_blank" rel="noopener sponsored nofollow">ADVERTISEMENT · Sponsored link ↗</a>`;
  return `<div class="adsterra-slot">${code}</div>`;
}
function adMarkup(key){
  const nets=configuredNetworks();
  if(nets.includes("adsterra"))return adsterraMarkup(key);
  if(nets.includes("adsense"))return adsenseMarkup(key);
  return `<div class="ad-slot-placeholder">ADVERTISEMENT · Ads are off — set <b>adNetwork.active</b> in <b>config/pricing.json</b></div>`;
}
function pushAds(){
  try{
    if(document.querySelector("ins.adsbygoogle")){
      (window.adsbygoogle=window.adsbygoogle||[]).push({});
    }
  }catch(_){}
}
function mountAdsterra(){
  if(!configuredNetworks().includes("adsterra"))return;
  $$("[data-adsterra-src]").forEach(h=>{
    if(h.getAttribute("data-mounted"))return;
    h.setAttribute("data-mounted","1");
    const tag=document.createElement("script");
    tag.async=true;
    tag.src=h.getAttribute("data-adsterra-src");
    tag.setAttribute("data-adsterra-banner","1");
    h.appendChild(tag);
  });
}
function loadAdSense(){
  if(!configuredNetworks().includes("adsense"))return;
  const a=P.adsense||{}, client=(a.client||"").trim();
  if(!a.enabled || !client || client.includes("XXXX"))return;
  if(document.querySelector("script[data-adsense-client]"))return;
  const tag=document.createElement("script");
  tag.async=true;
  tag.src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client="+encodeURIComponent(client);
  tag.setAttribute("crossorigin","anonymous");
  tag.setAttribute("data-adsense-client",client);
  document.head.appendChild(tag);
}
function loadAdsterraHead(){
  if(!configuredNetworks().includes("adsterra"))return;
  const a=P.adsterra||{}, url=(a.headScriptUrl||"").trim();
  if(!a.enabled || !url)return;
  if(document.querySelector("script[data-adsterra-head]"))return;
  const tag=document.createElement("script");
  tag.async=true;
  tag.src=url;
  tag.setAttribute("data-adsterra-head","1");
  document.head.appendChild(tag);
}

/* ---------- render ---------- */
function card(a){
  const dl=firstDownload(a);
  return `<article class="card" data-id="${esc(a.id)}">
    <div class="card-top">${icon(a)}<div class="card-actions">
      <button class="mini ${S.favorites.has(a.id)?"on":""}" data-fav="${esc(a.id)}" type="button" title="Favorite" aria-label="Favorite">${S.favorites.has(a.id)?"♥":"♡"}</button>
      <button class="mini" data-share="${esc(a.id)}" type="button" title="Share" aria-label="Share">↗</button>
    </div></div>
    <h3>${esc(a.name)}</h3><p class="sum">${esc(a.summary||"")}</p>
    <div class="tags">${tierBadge(a)}<span class="badge b-plat">${esc(a.platform||"Windows")}</span><span class="badge b-cat">${esc(a.category||"")}</span></div>
    <div class="card-foot"><span>v${esc(a.version||"Latest")}</span><span>${esc((a.published||"").slice(0,10)||"—")}</span></div>
    <div class="card-btns"><button class="btn btn-ghost btn-sm" data-detail="${esc(a.id)}" type="button">Details</button>
      <a class="btn btn-blue btn-sm" href="${esc(dl?dl.url:a.officialUrl||SITE.url)}" target="_blank" rel="noopener noreferrer" title="${esc(dl?dl.note||dl.host:"Official publisher")}">↓ Download</a></div>
  </article>`;
}
function filtered(){
  const q=S.query.trim().toLowerCase();
  let list=C.apps.filter(a=>{
    const hay=(a.name+" "+a.title+" "+a.summary+" "+a.category+" "+(a.tags||[]).join(" ")).toLowerCase();
    return (!q||hay.includes(q))&&(S.category==="All"||a.category===S.category)&&
      (S.platform==="All"||(a.platforms||[]).includes(S.platform))&&
      (S.tier==="All"||a.tier===S.tier);
  });
  const by={latest:(x,y)=>(y.published||"").localeCompare(x.published||""),trending:(x,y)=>y.trendingScore-x.trendingScore,
    name:(x,y)=>x.name.localeCompare(y.name),downloads:(x,y)=>y.downloadCount-x.downloadCount};
  return list.sort(by[S.sort]||by.latest);
}
function renderApps(){
  const list=filtered(),shown=list.slice(0,S.shown);
  $("#appGrid").innerHTML=shown.map(card).join("");
  $("#appEmpty").hidden=shown.length>0;
  if(!shown.length)$("#appEmpty").innerHTML=`<b>কিছু পাওয়া যায়নি</b>অন্য ক্যাটাগরি, প্ল্যাটফর্ম বা খোঁজার শব্দ চেষ্টা করুন।`;
  $("#loadMore").style.display=list.length>S.shown?"inline-flex":"none";
  $("#loadMore").textContent=`Load more apps ↓ (${list.length-S.shown>0?list.length-S.shown:0} left)`;
  $("#appCount").textContent=`${list.length} of ${C.apps.length} apps`;
  revealScan();
}
