/* ---------- live Blogger feed: show posts that are newer than the embedded catalog ---------- */
function loadLiveFeed(){
  try{
    if(!window.fetch||location.protocol==="file:")return;
    const norm=u=>String(u||"").replace(/^https?:/,"").replace(/[?#].*$/,"").replace(/\/$/,"");
    const known=new Set(C.apps.map(a=>norm(a.postUrl)));
    fetch("/feeds/posts/default?alt=json&max-results=150").then(r=>r.json()).then(j=>{
      const ents=(j.feed&&j.feed.entry)||[];let added=0;
      ents.forEach(e=>{
        const link=((e.link||[]).find(l=>l.rel==="alternate")||{}).href||"";
        if(!link||known.has(norm(link)))return;
        const title=(e.title&&e.title.$t)||"Untitled";
        const html=(e.content&&e.content.$t)||(e.summary&&e.summary.$t)||"";
        const text=html.replace(/<[^>]*>/g," ").replace(/\s+/g," ").trim();
        const img=(e["media$thumbnail"]&&e["media$thumbnail"].url)||((html.match(/<img[^>]+src=["']([^"']+)/i)||[])[1])||"";
        const cats=(e.category||[]).map(x=>x.term).filter(Boolean);
        const pub=((e.published&&e.published.$t)||"").slice(0,10);
        C.apps.push({id:String(((e.id&&e.id.$t)||link).split("post-").pop()),name:title,title:title,summary:text.slice(0,160),description:text.slice(0,400),features:[],category:cats[0]||"Apps",platform:"Windows",platforms:["Windows"],publisher:"",officialUrl:link,version:"Latest",license:"See post",formats:[],size:"",published:pub,updated:pub,postUrl:link,image:img,screenshots:img?[img]:[],downloads:[{label:"Open post",url:link,kind:"post",host:location.hostname}],withheld:[],tier:"free",badge:"FREE",downloadCount:1,trendingScore:1,tags:cats});
        known.add(norm(link));added++;
      });
      if(!added)return;
      const counts={};C.apps.forEach(a=>{counts[a.category]=(counts[a.category]||0)+1;});
      C.categories=Object.keys(counts).map(n=>({name:n,count:counts[n]})).sort((a,b)=>b.count-a.count);
      renderAll();
    }).catch(()=>{});
  }catch(e){}
}
function revealScan(){
  if(reduced){$$(".reveal").forEach(e=>e.classList.add("in"));return;}
  if(!("IntersectionObserver" in window)){$$(".reveal").forEach(e=>e.classList.add("in"));return;}
  const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("in");io.unobserve(e.target);}}),{threshold:.08});
  $$(".reveal:not(.in)").forEach(e=>io.observe(e));
}

/* ---------- modals ---------- */
function openModal(html){$("#modalCard").innerHTML=`<button class="modal-close" id="modalClose" type="button" aria-label="Close">✕</button>${html}`;$("#modal").classList.add("open");document.body.style.overflow="hidden";$("#modalClose").onclick=closeModal;pushAds();mountAdsterra();}
function closeModal(){$("#modal").classList.remove("open");document.body.style.overflow="";S.current=null;}
function relatedApps(a){return C.apps.filter(x=>x.id!==a.id&&(x.category===a.category||(x.platforms||[]).some(p=>(a.platforms||[]).includes(p)))).slice(0,4);}
function shareRow(a){
  const url=pageUrl(a),txt=shareText(a);
  const items=[
    ["Facebook","#1877F2",`https://www.facebook.com/sharer/sharer.php?u=${enc(url)}`],
    ["X / Twitter","#000000",`https://twitter.com/intent/tweet?url=${enc(url)}&text=${enc(txt)}`],
    ["Threads","#ec4899",`https://www.threads.net/intent/post?text=${enc(txt)}%20${enc(url)}`],
    ["WhatsApp","#25D366",`https://api.whatsapp.com/send?text=${enc(txt)}%20${enc(url)}`],
    ["Telegram","#2AABEE",`https://t.me/share/url?url=${enc(url)}&text=${enc(txt)}`],
    ["LinkedIn","#0A66C2",`https://www.linkedin.com/sharing/share-offsite/?url=${enc(url)}`],
    ["Instagram","#E1306C","instagram"],
    ["Copy link","#f472b6","copy"]
  ];
  return `<div class="share-row">${items.map(([n,c,v])=>`<button class="share-btn" data-share-to="${esc(v)}" data-share-name="${esc(n)}" type="button"><i style="background:${c}"></i>${esc(n)}</button>`).join("")}<button class="share-btn" data-native-share="1" type="button"><i style="background:#34d399"></i>Native share</button></div>`;
}
