  const rel=relatedApps(a).map(r=>`<button class="rel-card" data-detail="${esc(r.id)}" type="button">${icon(r,36)}<span><b>${esc(r.name)}</b><small>${esc(r.category)} · ${esc(r.tier==="premium"?"Premium":"Free")}</small></span></button>`).join("")||"<p style=\"font-size:11.5px;color:var(--muted)\">No related apps yet.</p>";
  const dl=firstDownload(a);
  openModal(`<div class="modal-hero"><div class="modal-hero-top">${icon(a,72)}<div><h2>${esc(a.name)}</h2><p>${esc(a.description||a.summary||"")}</p></div></div><div style="margin-top:14px;display:flex;gap:6px;flex-wrap:wrap">${tierBadge(a)}<span class="badge b-plat">${esc(a.platformNote||a.platform)}</span><span class="badge b-cat">${esc(a.category)}</span>${a.verified?'<span class="badge b-ver">✓ Verified</span>':""}</div></div>
