      <div class="info"><span>Formats</span><b>${esc((a.formats||[]).join(", "))}</b></div>
      <div class="info"><span>License / price</span><b>${esc(a.priceLabel||(a.tier==="premium"?"Publisher license":"Free"))}</b></div>
