      <div class="info"><span>Updated</span><b>${esc(a.updated||a.published||"—")}</b></div>
    </div>
    <div class="mh">In-article advertisement</div><div class="adslot" id="adInArticle">${adMarkup("inArticle")}</div>
    <div class="mh">Downloads (${(a.downloads||[]).length})</div><div>${dls||'<div class="empty"><b>No direct files listed</b>Open the original post for the latest links.</div>'}</div>
    ${(a.withheld||[]).length?`<div class="notice"><b>● ${a.withheld.length} link(s) withheld.</b> ${esc(a.withheld[0].reason||"License review required.")} Replace with official publisher URLs before submitting to any app store.</div>`:""}
    <div class="mh">Related apps</div><div class="related">${rel}</div>
