    <div class="modal-actions">
      <a class="btn btn-green" href="${esc(wa)}${a?`%20${enc("Product: "+a.name)}`:""}" target="_blank" rel="noopener">Buy / request via WhatsApp</a>
      ${a&&a.buyUrl?`<a class="btn btn-blue" href="${esc(a.buyUrl)}" target="_blank" rel="noopener">Official publisher license ↗</a>`:""}
      <button class="btn btn-ghost" data-request="1" type="button">Request another app</button>
    </div>
    <p class="form-note">● শুধুমাত্র বৈধ লাইসেন্স বা অনুমোদিত সোর্স ব্যবহার করুন। MH Apps Gallery ক্র্যাক/প্যাচ/অননুমোদিত কপি বিক্রি করে না — প্রিমিয়াম বাটনটি আপনাকে অফিশিয়াল publisher বা আপনার নিজস্ব চেকআউটে পাঠায়।</p>
  </div>`);
}
function openRequest(){
  const r=P.request||{};
  openModal(`<div class="modal-hero"><div class="modal-hero-top"><div class="app-icon" style="width:68px;height:68px;background:linear-gradient(135deg,#a855f7,#f472b6)"><span>↑</span></div><div><h2>Request a software upload</h2><p>ফর্মটি পূরণ করুন — আমরা WhatsApp বা ইমেইলে প্রি-ফিলড রিকোয়েস্ট তৈরি করে দেব।</p></div></div></div>
  <div class="modal-body"><form id="requestForm" class="form-grid">
    <div class="field"><label for="rqName">আপনার নাম</label><input id="rqName" required placeholder="আপনার নাম"></div>
    <div class="field"><label for="rqContact">Email / WhatsApp</label><input id="rqContact" placeholder="আপনার যোগাযোগ"></div>
    <div class="field"><label for="rqApp">Software-এর নাম *</label><input id="rqApp" required placeholder="যেমন: Photoshop 2027"></div>
    <div class="field"><label for="rqPlat">Platform</label><select id="rqPlat"><option>Windows</option><option>Android</option><option>macOS</option><option>iOS</option><option>Linux</option><option>Web</option></select></div>
    <div class="field full"><label for="rqLink">অফিশিয়াল লিংক (যদি থাকে)</label><input id="rqLink" placeholder="https://…"></div>
    <div class="field full"><label for="rqMsg">বিস্তারিত</label><textarea id="rqMsg" placeholder="কোন ভার্শন, ফ্রি না প্রিমিয়াম, কেন চাচ্ছেন…"></textarea></div>
    <div class="field full"><button class="btn btn-blue" type="submit">Generate request →</button></div>
  </form>
  <div id="requestResult"></div>
  <p class="form-note">${esc(r.instructions||"")} Google Form সেট করা থাকলে নিচে সরাসরি লিংক পাবেন।</p></div>`);
  $("#requestForm").onsubmit=submitRequest;
}
function submitRequest(e){
  e.preventDefault();
  const g=id=>$("#"+id).value.trim();
  const body=`Software upload request\nName: ${g("rqName")}\nContact: ${g("rqContact")}\nSoftware: ${g("rqApp")}\nPlatform: ${g("rqPlat")}\nOfficial link: ${g("rqLink")||"—"}\nDetails: ${g("rqMsg")||"—"}`;
  const r=P.request||{},wa=r.whatsapp||"https://wa.me/8801540085661",mail=r.email||"";
  $("#requestResult").innerHTML=`<div class="mh">আপনার রিকোয়েস্ট তৈরি হয়েছে</div>
    <div class="notice" style="white-space:pre-wrap;border-color:rgba(52,211,153,.35);background:rgba(52,211,153,.08)">${esc(body)}</div>
    <div class="modal-actions">
      <a class="btn btn-green" href="${esc(wa.split("?")[0]+"?text="+enc(body))}" target="_blank" rel="noopener">Send via WhatsApp ↗</a>
      ${mail?`<a class="btn btn-ghost" href="mailto:${esc(mail)}?subject=${enc("Software upload request")}&body=${enc(body)}" target="_blank">Send by email ↗</a>`:""}
      ${r.googleFormUrl?`<a class="btn btn-blue" href="${esc(r.googleFormUrl)}" target="_blank" rel="noopener">Open Google Form ↗</a>`:""}
      <button class="btn btn-ghost" id="copyReq" type="button">Copy request</button>
    </div>`;
  $("#copyReq").onclick=()=>{navigator.clipboard?.writeText(body).then(()=>toast("Request copied"),()=>toast(body.slice(0,80)));};
  toast("Request ready — choose how to send it.");
}
function doShare(v,name,a){
  const url=pageUrl(a),txt=shareText(a);
  if(v==="copy"){navigator.clipboard?.writeText(url).then(()=>toast("Link copied to clipboard"),()=>toast(url));return;}
  if(v==="instagram"){
    navigator.clipboard?.writeText(txt+" "+url).then(()=>toast("Caption copied — paste it in Instagram"),()=>{});
    window.open("https://www.instagram.com/","_blank","noopener");return;
  }
  window.open(v,"_blank","noopener,noreferrer,width=680,height=560");
}
function nativeShare(a){
  const data={title:a?a.name:SITE.name,text:shareText(a),url:pageUrl(a)};
  if(navigator.share){navigator.share(data).catch(()=>{});}else{doShare("copy","Copy link",a);}
}

/* ---------- events ---------- */
document.addEventListener("click",e=>{
  const t=e.target.closest("[data-detail],[data-fav],[data-share],[data-cat],[data-plan],[data-buy],[data-request],[data-share-to],[data-native-share],[data-share-site]");
  if(t){
    if(t.dataset.fav){const id=t.dataset.fav;S.favorites.has(id)?S.favorites.delete(id):S.favorites.add(id);SAFE.set("mhag2-favs",JSON.stringify([...S.favorites]));renderApps();toast(S.favorites.has(id)?"Added to favorites":"Removed from favorites");return;}
    if(t.dataset.detail){openDetail(t.dataset.detail);$("#modal").scrollTop=0;return;}
    if(t.dataset.share){const a=findApp(t.dataset.share);if(a){openDetail(a.id);setTimeout(()=>$("#modal").scrollTop=99999,60);}return;}
    if(t.dataset.cat){S.category=t.dataset.cat;S.shown=12;renderAll();document.getElementById("apps").scrollIntoView({behavior:"smooth"});return;}
    if(t.dataset.plan){openBuy(t.dataset.plan==="premium"?null:null);return;}
    if(t.dataset.buy){openBuy(t.dataset.buy);return;}
    if(t.dataset.request){openRequest();return;}
    if(t.dataset.shareTo){doShare(t.dataset.shareTo,t.dataset.shareName,S.current);return;}
    if(t.dataset.nativeShare){nativeShare(S.current);return;}
    if(t.dataset.shareSite){e.preventDefault();S.current=null;openModal(`<div class="modal-hero"><div class="modal-hero-top"><div class="app-icon" style="width:68px;height:68px;background:linear-gradient(135deg,#a855f7,#f472b6)"><span>↗</span></div><div><h2>Share MH Apps Gallery</h2><p>আপনার পছন্দের প্ল্যাটফর্মে এই সাইটটি শেয়ার করুন।</p></div></div></div><div class="modal-body"><div class="mh">Social platforms</div>${shareRow(null)}<p class="form-note">Instagram-এ সরাসরি ওয়েব শেয়ার API নেই — বাটনটি caption কপি করে Instagram খুলে দেয়। Facebook, X ও Threads = Meta প্ল্যাটফর্ম।</p></div>`);return;}
  }
  if(e.target.id==="modal"||e.target.id==="modalClose"){closeModal();return;}
  const jump=e.target.closest('[data-cat-jump]');
  if(jump){setTimeout(()=>$("#catChips").scrollIntoView({behavior:"smooth",block:"center"}),350);}
});
$("#modal").addEventListener("click",e=>{if(e.target.closest("[data-detail],[data-buy],[data-request]")){$("#modal").scrollTop=0;}});
$("#appSearch").addEventListener("input",e=>{S.query=e.target.value;S.shown=12;renderApps();});
$("#globalSearch").addEventListener("input",e=>{S.query=e.target.value;S.shown=12;$("#appSearch").value=e.target.value;renderApps();$("#searchHints").textContent=e.target.value?`${filtered().length} apps matching “${e.target.value}”`:"Start typing to filter the whole gallery.";});
$("#platformSel").addEventListener("change",e=>{S.platform=e.target.value;S.shown=12;renderApps();});
$("#tierSel").addEventListener("change",e=>{S.tier=e.target.value;S.shown=12;renderApps();});
$("#sortSel").addEventListener("change",e=>{S.sort=e.target.value;S.shown=12;renderApps();});
$("#loadMore").addEventListener("click",()=>{S.shown+=12;renderApps();});
$("#searchToggle").addEventListener("click",()=>{$("#hdrSearch").classList.toggle("open");if($("#hdrSearch").classList.contains("open"))$("#globalSearch").focus();});
$("#menuToggle").addEventListener("click",()=>$("#nav").classList.toggle("open"));
(function(){
  var B="https://github.com/hossenuser/Host-Web/releases/download/latest-build/";
  var items=[["Windows (.exe)","Windows 10 / 11","~89 MB","MH-Apps-Gallery-Setup.exe"],["Android (.apk)","Android phone / tablet","~5 MB","app-debug.apk"],["Mac (.dmg)","Apple Silicon (M1 / M2 / M3)","~106 MB","MH-Apps-Gallery-arm64.dmg"]];
  function openDownloads(){
    var logo=($("#hdrLogo")&&$("#hdrLogo").src)||"";
    var btns=items.map(function(i){return '<a class="dl-btn" rel="noopener" href="'+B+i[3]+'"><span>'+i[0]+'<small>'+i[1]+'</small></span><span class="dl-size">'+i[2]+'</span></a>';}).join("");
    openModal('<div class="dl-box" style=\'--dlLogo:url('+JSON.stringify(logo)+')\'><div class="dl-in"><h3>MH Apps Gallery</h3><p class="dl-sub">Download the app</p>'+btns+'<p class="dl-note"><b>Windows:</b> "Windows protected your PC" দেখালে <b>More info → Run anyway</b> চাপুন।<br><b>Android:</b> "Install unknown apps" অনুমতি দিন।<br><b>Mac:</b> অ্যাপে Right-click করে <b>Open</b> চাপুন।</p></div></div>');
  }
  document.querySelectorAll("[data-dl]").forEach(function(b){b.addEventListener("click",function(){$("#nav").classList.remove("open");openDownloads();});});
})();
$("#themeToggle").addEventListener("click",()=>{S.theme=S.theme==="dark"?"light":"dark";SAFE.set("mhag2-theme",S.theme);applyTheme();});
function applyTheme(){document.documentElement.dataset.theme=S.theme;$("#themeIcon").innerHTML=S.theme==="dark"?'<path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"></path>':'<circle cx="12" cy="12" r="4"></circle><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"></path>';const m=$('meta[name="theme-color"]');if(m)m.content=S.theme==="dark"?"#0d0714":"#f4f7fd";}
$("#chatFab").addEventListener("click",()=>$("#chatPanel").classList.toggle("open"));
[["#openRequest",openRequest],["#sideRequest",openRequest]].forEach(([sel,fn])=>{const b=$(sel);if(b)b.addEventListener("click",fn);});
$("#sideChat").addEventListener("click",()=>$("#chatPanel").classList.add("open"));
$("#openChatFromRequest").addEventListener("click",()=>$("#chatPanel").classList.add("open"));
$("#privacyLink").addEventListener("click",e=>{
  e.preventDefault();
  const policy=esc(SITE.privacy||"This site reads the public Blogger feed and stores only your theme choice and favorites on your device. No account, no tracking, no analytics, no data collection. Download links open in your browser or the source website.");
  openModal('<div class="modal-hero"><div class="modal-hero-top"><div class="app-icon" style="width:68px;height:68px;background:linear-gradient(135deg,#a855f7,#f472b6)"><span>P</span></div><div><h2>Privacy policy</h2><p>MH Apps Gallery</p></div></div></div><div class="modal-body"><p style="font-size:12.5px;line-height:1.8;color:var(--muted)">'+policy+'</p></div>');
});

document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeModal();$("#chatPanel").classList.remove("open");}if(e.key==="/"&&document.activeElement.tagName!=="INPUT"&&document.activeElement.tagName!=="TEXTAREA"){e.preventDefault();$("#hdrSearch").classList.add("open");$("#globalSearch").focus();}});

/* ---------- 3D tilt + intro ---------- */
function initTilt(){
  if(reduced||window.matchMedia("(pointer: coarse)").matches)return;
  const card=$("#tiltCard");if(!card)return;
  card.addEventListener("mousemove",e=>{const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`rotateY(${x*16}deg) rotateX(${-y*16}deg) translateZ(0)`;});
  card.addEventListener("mouseleave",()=>{card.style.transform="rotateY(0) rotateX(0)";});
}

/* ---------- optional: live catalog refresh + embedded chat ---------- */
function refreshPublishedCatalog(){
  const url=(P.publishedCatalogUrl||"").trim();
  if(!url||!window.fetch)return;
  fetch(url,{cache:"no-store"}).then(r=>r.ok?r.json():null).then(data=>{
    if(data&&Array.isArray(data.apps)&&data.apps.length){
      C=data;renderAll();console.info("MH Apps Gallery: catalog refreshed from "+url);
    }
  }).catch(()=>{/* offline: embedded catalog is authoritative */});
}
function loadChatProvider(){
  const ch=P.chat||{};
  try{
    if(ch.tawkToId){
      window.Tawk_API=window.Tawk_API||{};window.Tawk_LoadStart=new Date();
      const s=document.createElement("script");s.async=true;s.src="https://embed.tawk.to/"+encodeURIComponent(ch.tawkToId)+"/default";s.charset="UTF-8";s.setAttribute("crossorigin","*");document.head.appendChild(s);
    }else if(ch.crispId){
      window.$crisp=[];window.CRISP_WEBSITE_ID=ch.crispId;
      const s=document.createElement("script");s.async=true;s.src="https://client.crisp.chat/l.js";document.head.appendChild(s);
    }
  }catch(_){}
}

/* ---------- boot ---------- */
(function boot(){
  applyTheme();renderAll();revealScan();initTilt();loadLiveFeed();
  refreshPublishedCatalog();loadChatProvider();loadAdSense();loadAdsterraHead();
  if(location.hash==="#pricing")$("#pricing").scrollIntoView();
})();
})();

